-- EraLens period import: song-liao-jin
-- Window: 916-01 .. 1234-12
BEGIN;

-- cleanup
-- remove stale auto-generated 史料缺 (太祖卒后述律太后摄政期应留白)
DELETE FROM reigns WHERE dynasty_id IN ('liao') AND person_id = 'system-missing-ruler';

-- persons
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-abaoji', '耶律阿保机', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '契丹迭剌部首领，辽太祖，整合契丹诸部并扩张其势力，916年称帝，建立辽朝。其统治奠定契丹国家制度与后续经营农耕地区的基础，在位916—926年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律阿保机"}]'::jsonb, NULL, '太祖', '辽太祖')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-deguang', '耶律德光', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽太宗耶律阿保机次子，承继皇位后南下争夺中原，灭后晋并于947年进入汴京。辽军随后北撤，辽朝势力一度深入华北；在位927—947年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律德光"}]'::jsonb, NULL, '太宗', '辽太宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-ruan', '耶律阮', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽太宗侄、辽世宗，太宗死后在辽军中被拥立，继位引发宗室权力冲突。他在位期间持续应对内部争位与后周压力，951年南征途中被近侍刺杀；在位947—951年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律阮"}]'::jsonb, NULL, '世宗', '辽世宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-jing', '耶律璟', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽太宗之子、辽穆宗，承接世宗遇弑后的皇位，长期统治但少有对外扩张。其晚年政局动荡，969年被近侍刺杀，景宗继位；在位951—969年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律璟"}]'::jsonb, NULL, '穆宗', '辽穆宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-xian', '耶律贤', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽世宗之子、辽景宗，在位时任用萧绰等人整顿政务，并在高梁河之战后维持辽宋边境格局。他与皇后萧绰所生的耶律隆绪继位，辽朝由此进入长期稳定发展阶段；在位969—982年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律贤"}]'::jsonb, NULL, '景宗', '辽景宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-longxu', '耶律隆绪', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽景宗之子、辽圣宗，幼年即位，由母亲萧绰摄政；亲政后继续改革官制、整合南北面治理。辽与北宋在澶州交战后缔结澶渊之盟，形成长期和平关系；在位982—1031年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律隆绪"}]'::jsonb, NULL, '圣宗', '辽圣宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-zongzhen', '耶律宗真', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽圣宗之子、辽兴宗，在位期间辽宋维持澶渊之盟，但与西夏的外交及军事关系趋于紧张。其朝廷经历宫廷权力斗争，皇位由长子耶律洪基承继；在位1031—1055年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律宗真"}]'::jsonb, NULL, '兴宗', '辽兴宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-hongji', '耶律洪基', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽兴宗之子、辽道宗，长期在位，前期辽宋关系总体延续和平，后期则受宫廷党争及冤狱影响，政治秩序转弱。女真势力在辽东北部兴起，成为辽朝晚期的重要压力；在位1055—1101年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律洪基"}]'::jsonb, NULL, '道宗', '辽道宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-yanxi', '耶律延禧', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽道宗之孙、辽天祚帝，继位时辽朝已面临女真崛起与内部离心。金军接连攻取辽地，他辗转逃亡并于1125年被俘，辽朝主体政权覆亡；在位1101—1125年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律延禧"}]'::jsonb, NULL, NULL, '辽天祚帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-aguda', '完颜阿骨打', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '女真完颜部首领，金太祖，整合女真诸部后于1114年起兵反辽，次年称帝建金。金军迅速削弱辽朝，并开启与北宋联合灭辽、随后转而攻宋的局面；在位1115—1123年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜阿骨打"}]'::jsonb, NULL, '太祖', '金太祖')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-sheng', '完颜晟', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金太祖之弟、金太宗，继位后攻灭辽朝，并在靖康之变中攻陷开封、俘虏宋徽宗与宋钦宗。金朝由东北政权扩张至华北，在位1123—1135年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜晟"}]'::jsonb, NULL, '太宗', '金太宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-dan', '完颜亶', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金太宗之侄、金熙宗，在位初期由宗室大臣辅政，随后推行官制与礼制改革、加强皇权。宫廷政争加剧后，他于1149年被完颜亮发动政变弑杀；在位1135—1149年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜亶"}]'::jsonb, NULL, '熙宗', '金熙宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-liang', '完颜亮', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金太祖之孙、金海陵王，以政变夺位后强化中央集权，并于1153年迁都燕京（中都）。他发动南征宋朝，采石之战受挫后遭军中政变杀害；在位1150—1161年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜亮"}]'::jsonb, NULL, NULL, '海陵王')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-yong', '完颜雍', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金太祖孙、金世宗，在海陵王南征时于辽阳起兵，被拥立为帝。即位后结束南征，与南宋议和，整顿吏治并恢复经济，后世以“大定之治”称其朝；在位1161—1189年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜雍"}]'::jsonb, NULL, '世宗', '金世宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-jing', '完颜璟', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金世宗之孙、金章宗，在位时延续金朝制度与文化建设，重视法令、典章和文学艺术。其后期黄河水患、财政压力及对外冲突增多，盛世基础渐受侵蚀；在位1189—1208年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜璟"}]'::jsonb, NULL, '章宗', '金章宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-yongji', '完颜永济', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金世宗之子、金卫绍王，章宗无子而由其继位，朝廷权力受到权臣掣肘。蒙古崛起并进攻金境，完颜珣政变后将其处死；在位1208—1213年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜永济"}]'::jsonb, NULL, NULL, '卫绍王')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-xun', '完颜珣', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金世宗之孙、金宣宗，政变后即位，面对蒙古大军围攻中都，于1214年迁都南京（开封）。南迁虽暂避兵锋，却引发金与南宋冲突，蒙古持续南侵使金朝战略处境恶化；在位1213—1223年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜珣"}]'::jsonb, NULL, '宣宗', '金宣宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-shouxu', '完颜守绪', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金宣宗之子、金哀宗，在蒙古持续进攻下辗转防守，曾尝试联合南宋抗蒙而未能扭转战局。蔡州被围时传位于完颜承麟，随后自缢，金朝灭亡；在位1223—1234年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜守绪"}]'::jsonb, NULL, '哀宗', '金哀宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('wanyan-chenglin', '完颜承麟', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '金哀宗末年在蔡州城破前受禅即位，是金朝最后一位皇帝。其即位当天金军破城，他在巷战中阵亡，金朝至此覆亡；在位1234年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/完颜承麟"}]'::jsonb, NULL, NULL, '金末帝')
